import { useEffect } from 'react';
import { useTranslation } from 'react-i18next';

import { notification } from 'antd';

import { ISource, useAddVerificationMutation } from 'entities/Source';

export const useSourceVerification = (source: ISource) => {
	const { t } = useTranslation();
	const [addVerification, { isLoading, isSuccess }] = useAddVerificationMutation();

	useEffect(() => {
		if (!isSuccess) return;

		notification.open({
			message: t('Заявка на верификацию отправлена успешно'),
			description: t(
				'После подтверждения владения {{sourceName}}, последняя автоматически попадет на модерацию и после ее прохождения можно подавать заявки на подключение к офферам.',
				{ sourceName: source.name },
			),
			type: 'success',
			placement: 'topRight',
			showProgress: true,
			pauseOnHover: true,
		});
	}, [isSuccess]); // eslint-disable-line

	return {
		addVerification,
		isLoading,
	};
};
