import { FC, HTMLAttributes } from 'react';

import { Flex, Typography } from 'antd';

import { ISource } from 'entities/Source/model/types';

const { Text } = Typography;
interface ISourceNameProps extends HTMLAttributes<HTMLDivElement> {
	source: ISource;
}

export const SourceName: FC<ISourceNameProps> = ({ source, ...props }) => {
	return (
		<Flex {...props} vertical>
			<Text ellipsis={{ tooltip: source.name }} style={{ maxWidth: 230 }}>
				{source.name}
			</Text>

			<Text type="secondary" copyable style={{ fontSize: 11 }}>
				{source.uuid}
			</Text>
		</Flex>
	);
};
