import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { useNavigate } from 'react-router-dom';

import { Button } from 'antd';

import { useMedia } from 'shared/hooks';
import { EMainRoutes, EYmEvents, EYmEventsO1, EYmEventsO2 } from 'shared/typings';
import { Page, PageTitle } from 'shared/ui';
import { sendYmEvent } from 'shared/utils';
import { SourceList } from 'widgets/SourceList';

interface ISourcesProps extends HTMLAttributes<HTMLDivElement> {}

export const Sources: FC<ISourcesProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const navigate = useNavigate();
	const isMd = useMedia();

	const handleCreateSourceClick = () => {
		sendYmEvent({
			event: EYmEvents.CLICK_ADD_ADSPACE,
			o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.ADSPACE],
			o2: EYmEventsO2.ADSPACE,
		});
		navigate(`/${EMainRoutes.SOURCES}/${EMainRoutes.CREATE}`);
	};
	return (
		<Page {...props} className={className}>
			<PageTitle
				//subtitle={t('Здесь можно представить краткое описание раздела')}
				component={
					<Button size="small" color="primary" variant="outlined" block={isMd} onClick={handleCreateSourceClick}>
						+ {t('Добавить площадку')}
					</Button>
				}>
				{t('Мои площадки')}
			</PageTitle>
			<SourceList />
		</Page>
	);
};

export default Sources;
