import { HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { Link } from 'react-router-dom';

import { MenuProps, Tooltip } from 'antd';

import DeleteIcon from 'assets/images/icons/delete.svg?react';
import EditIcon from 'assets/images/icons/edit.svg?react';
import InfoIcon from 'assets/images/icons/info.svg?react';
import VerifyIcon from 'assets/images/icons/verify.svg?react';
import { useSourceVerification } from 'entities/Source/hooks/useSourceVerification';
import { ESourceStatuses, ESourceTypes, ISource } from 'entities/Source/model/types';
import { EMainRoutes, EYmEvents, EYmEventsO1, EYmEventsO2 } from 'shared/typings';
import { TableDropdown } from 'shared/ui';
import { sendYmEvent } from 'shared/utils';

export interface ISourceDropdownProps extends HTMLAttributes<HTMLDivElement> {
	onDelete: () => void;
	source: ISource;
}

export const SourceDropdown = ({ onDelete, source }: ISourceDropdownProps) => {
	const { t } = useTranslation();
	const { addVerification } = useSourceVerification(source);

	const canEdit = source.status === ESourceStatuses.NEW || source.status === ESourceStatuses.REJECTED;

	const menuItems: MenuProps['items'] = [
		{
			label: <Link to={`/${EMainRoutes.SOURCES}/${source.uuid}`}>{t('Детали')}</Link>,
			key: 'details',
			icon: <InfoIcon />,
			onClick: () =>
				sendYmEvent({
					event: EYmEvents.CLICK_DETAILS_ADSPACE,
					o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.ADSPACE],
					o2: [EYmEventsO2.ADSPACE, EYmEventsO2.MENU],
					wi: source.uuid,
					isMarketing: false,
				}),
		},
		{
			label: canEdit ? (
				<Link to={`/${EMainRoutes.SOURCES}/${EMainRoutes.EDIT}/${source.uuid}`}>{t('Редактировать')}</Link>
			) : (
				<Tooltip title={t('В текущем статусе редактирование площадки недоступно')}>{t('Редактировать')}</Tooltip>
			),
			disabled: !canEdit,
			key: 'edit',
			icon: (
				<Tooltip title={canEdit ? undefined : t('В текущем статусе редактирование площадки недоступно')}>
					<EditIcon />
				</Tooltip>
			),
			onClick: () =>
				sendYmEvent({
					event: EYmEvents.CLICK_EDIT_ADSPACE,
					o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.ADSPACE],
					o2: [EYmEventsO2.ADSPACE, EYmEventsO2.MENU],
					wi: source.uuid,
					isMarketing: false,
				}),
		},
	];

	if (canEdit) {
		menuItems.push({
			label:
				source.type === ESourceTypes.WEBSITE ? (
					<Link to={`/${EMainRoutes.SOURCES}/${EMainRoutes.VERIFICATION}/${source.uuid}`}>{t('Верифицировать')}</Link>
				) : (
					t('Верифицировать')
				),
			onClick: () => {
				sendYmEvent({
					event: EYmEvents.CLICK_VERIFY_ADSPACE,
					o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.ADSPACE],
					o2: [EYmEventsO2.ADSPACE, EYmEventsO2.MENU],
					wi: source.uuid,
					isMarketing: false,
				});
				source.type !== ESourceTypes.WEBSITE && addVerification({ body: { source_pk: source.uuid } });
			},
			key: 'verify',
			icon: <VerifyIcon />,
		});
	}

	menuItems.push({
		type: 'divider',
	});

	menuItems.push({
		label: t('Удалить'),
		key: 'delete',
		icon: <DeleteIcon />,
		onClick: () => {
			sendYmEvent({
				event: EYmEvents.CLICK_DELETE_ADSPACE,
				o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.ADSPACE],
				o2: [EYmEventsO2.ADSPACE, EYmEventsO2.MENU],
				wi: source.uuid,
				isMarketing: false,
			});
			onDelete();
		},
		danger: true,
	});

	return (
		<TableDropdown
			menuItems={menuItems}
			onOpenChange={(open) =>
				open &&
				sendYmEvent({
					event: EYmEvents.CLICK_MENU_ADSPACE,
					o1: [EYmEventsO1.ACCOUNT, EYmEventsO1.PUBLISHER, EYmEventsO1.ADSPACE],
					o2: EYmEventsO2.ADSPACE,
					wi: source.uuid,
					isMarketing: false,
				})
			}
		/>
	);
};

export default SourceDropdown;
