import { FC, HTMLAttributes, ReactNode, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useSearchParams } from 'react-router-dom';

import { Flex, Table, TableColumnsType } from 'antd';

import { DeleteSourceModal, getSource, ISource, useGetSourceListQuery } from 'entities/Source';
import { Pagination } from 'features/Pagination';
import { EMainRoutes } from 'shared/typings';
import { EmptyState, OverlayLoader } from 'shared/ui';
import { getDefaultSortOrder, getTableSorter } from 'shared/utils';

interface DataType {
	key: React.Key;
	name: ReactNode;
	status: ReactNode;
	joined_offers_count: ReactNode;
	comment: ReactNode;
	menu: ReactNode;
}

interface ISourceListProps extends HTMLAttributes<HTMLDivElement> {}

export const SourceList: FC<ISourceListProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const [deletingSource, setDeletingSource] = useState<ISource | null>(null);
	const [searchParams, setSearchParams] = useSearchParams();
	const { data, isFetching } = useGetSourceListQuery(searchParams.toString());
	const hasData = !!data?.results?.length;

	const columns: TableColumnsType<DataType> = [
		{
			dataIndex: 'name',
			key: 'name',
			title: `${t('Площадка')}`,
			defaultSortOrder: getDefaultSortOrder('name', searchParams),
			sorter: true,
		},
		{
			dataIndex: 'status',
			key: 'status',
			title: t('Статус'),
			defaultSortOrder: getDefaultSortOrder('status', searchParams),
			sorter: true,
		},
		{
			dataIndex: 'joined_offers_count',
			key: 'joined_offers_count',
			title: t('Подключено офферов'),
			defaultSortOrder: getDefaultSortOrder('joined_offers_count', searchParams),
			sorter: true,
		},
		{
			dataIndex: 'comment',
			key: 'comment',
			title: t('Комментарий'),
		},
		{
			dataIndex: 'menu',
			key: 'menu',
			fixed: 'right',
			width: 50,
		},
	];

	const dataSource = hasData
		? data?.results?.map<DataType>((source, i) => {
				return getSource(source, i, () => setDeletingSource(source));
			})
		: [];

	return (
		<Flex vertical gap={20} {...props} className={className}>
			{isFetching && <OverlayLoader />}

			{!hasData && !isFetching && (
				<EmptyState
					title={t('Пока нет созданных площадок')}
					buttonText={`+ ${t('Добавить площадку')}`}
					buttonTo={`/${EMainRoutes.SOURCES}/${EMainRoutes.CREATE}`}
				/>
			)}

			{hasData && (
				<>
					<Table<DataType>
						columns={columns}
						dataSource={dataSource}
						bordered={false}
						scroll={{ x: 'max-content' }}
						pagination={false}
						showSorterTooltip={false}
						onChange={getTableSorter<DataType>(searchParams, setSearchParams)}
					/>

					<Pagination count={data?.count || 1} />
				</>
			)}

			<DeleteSourceModal source={deletingSource} setDeletingSource={setDeletingSource} />
		</Flex>
	);
};
