import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { Link } from 'react-router-dom';

import { Button } from 'antd';

import { ESourceTypes, ISource, useSourceVerification } from 'entities/Source';
import { EMainRoutes } from 'shared/typings';

interface ISourceVerificationProps extends HTMLAttributes<HTMLDivElement> {
	source: ISource;
}

export const SourceVerification: FC<ISourceVerificationProps> = ({ source, ...props }) => {
	const { t } = useTranslation();

	const { addVerification, isLoading } = useSourceVerification(source);

	return (
		<div {...props}>
			{t('Требуется подтвердить владение площадкой')}{' '}
			{source.type === ESourceTypes.WEBSITE && (
				<Link
					to={`/${EMainRoutes.SOURCES}/${EMainRoutes.VERIFICATION}/${source.uuid}`}
					style={{ textDecoration: 'underline' }}>
					{t('Верифицировать')}
				</Link>
			)}
			{source.type !== ESourceTypes.WEBSITE && (
				<Button
					type="link"
					onClick={() => addVerification({ body: { source_pk: source.uuid } })}
					style={{ textDecoration: 'underline', padding: 0, height: 22 }}
					loading={isLoading}
					disabled={isLoading}>
					{t('Верифицировать')}
				</Button>
			)}
		</div>
	);
};
