import { MoreOutlined } from '@ant-design/icons';

import { Button, Dropdown, DropdownProps, MenuProps } from 'antd';

export interface ITableDropdownProps extends DropdownProps {
	menuItems: MenuProps['items'];
}

export const TableDropdown = ({ className, menuItems, ...props }: ITableDropdownProps) => {
	return (
		<Dropdown {...props} className={className} menu={{ items: menuItems }} placement="bottomLeft" trigger={['click']}>
			<Button type="text" size="small" icon={<MoreOutlined />} />
		</Dropdown>
	);
};

export default TableDropdown;
