import { Link } from 'react-router-dom';

import {
	ESourceStatuses,
	ISource,
	SourceDropdown,
	SourceName,
	SourceStatus,
	SourceVerification,
} from 'entities/Source';
import { EFilters } from 'features/Filters';
import { EMainRoutes, EStatuses } from 'shared/typings';

export const getSource = (source: ISource, key: number, onDelete: () => void) => {
	const { uuid, status, joined_offers_count, rejection_comment } = source;

	return {
		key,
		name: <SourceName source={source} />,
		status: <SourceStatus sourceStatus={status} />,
		joined_offers_count: (
			<Link
				to={`/${EMainRoutes.CATALOG}/?${EFilters.SOURCE}=${uuid}&${EFilters.STATUS}=${EStatuses.JOINED}`}
				style={{ textDecoration: 'underline' }}>
				{joined_offers_count}
			</Link>
		),
		comment: (
			<div style={{ maxWidth: 240 }}>
				{status === ESourceStatuses.NEW ? <SourceVerification source={source} /> : rejection_comment || '-'}
			</div>
		),
		menu: <SourceDropdown onDelete={onDelete} source={source} />,
	};
};
