import { FC, useEffect } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Flex, Modal, ModalProps, Typography } from 'antd';

import { useDeleteSourceMutation } from 'entities/Source/api/api';
import { ISource } from 'entities/Source/model/types';

interface IDeleteSourceModalProps extends ModalProps {
	source: ISource | null;
	setDeletingSource: (source: ISource | null) => void;
}

export const DeleteSourceModal: FC<IDeleteSourceModalProps> = ({ source, setDeletingSource, ...props }) => {
	const { t } = useTranslation();

	const [deleteSource, { isLoading, isSuccess }] = useDeleteSourceMutation();

	useEffect(() => {
		if (isSuccess) {
			setDeletingSource(null);
		}
	}, [isSuccess]); // eslint-disable-line

	if (!source) return null;

	return (
		<Modal
			{...props}
			open={!!source}
			footer={null}
			closable={true}
			maskClosable={true}
			onCancel={() => setDeletingSource(null)}>
			<Flex vertical gap={24}>
				<Typography.Title level={4} style={{ margin: 0 }}>
					{t('Удалить {{sourceName}}?', { sourceName: source.name })}
				</Typography.Title>

				<Typography.Text type="secondary" style={{ fontSize: 16 }}>
					{t('После удаления все подключенные офферы будут сброшены, и сайт не сможет быть восстановлен.')}
				</Typography.Text>

				<Flex justify="space-between">
					<Button onClick={() => setDeletingSource(null)}>{t('Отменить')}</Button>
					<Button
						variant="solid"
						color="danger"
						loading={isLoading}
						disabled={isLoading}
						onClick={() => deleteSource(source.uuid)}>
						{t('Удалить')}
					</Button>
				</Flex>
			</Flex>
		</Modal>
	);
};
